import json, html
from pathlib import Path
source=json.loads(Path('research/phone-source.json').read_text(encoding='utf-8'))
topics=[]; items=[]
def topic(id,title,refs):
 topics.append(dict(id=id,title=title,description='Речевой выбор в пограничных ситуациях: '+title.lower()+'.',sectionRef='Стандарт · '+source[refs[0]].strip()))
 return id
def add(t,kind,refs,prompt,context,choices,why):
 assert len(choices)==len(why)==4
 n=sum(i['topicId']==t and i['kind']==kind for i in items)+1
 items.append(dict(id=f'phone-{t}-{kind}-{n}',topicId=t,kind=kind,difficulty='medium' if kind=='question' else 'hard',question=prompt,wolfContext=context,options=choices,correctIndex=0,explanation=why[0]+' В этой ситуации решающим является условие из приведённой выдержки, а не просто вежливость формулировки.',optionReasons=why,sourcePage=1,sourceClause=f'phone-{refs[0]}',clauseRef='Телефонный стандарт · '+source[refs[0]].strip(),sourceExcerpt='\n'.join(source[r].strip() for r in refs[1:]),sourceAnchor=f'phone-{refs[0]}'))
def q(t,r,p,c,w):add(t,'question',r,p,'Выберите подход, который точнее соответствует стандарту в заданных условиях.',c,w)
def c(t,r,p,ctx,opts,w):add(t,'case',r,p,ctx,opts,w)

